class Solution {
    public List<Integer> lexicalOrder(int n){
        List<Integer> answer=new ArrayList<>(n);
        int current=1;
        for(int count=0;count<n;count++){
            answer.add(current);
            if((long)current*10<=n)current*=10;
            else{
                while(current%10==9||current+1>n)current/=10;
                current++;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun lexicalOrder(n:Int):List<Int>{
        val answer=ArrayList<Int>(n);
        var current=1;
        repeat(n){
            answer.add(current);
            if(current.toLong()*10<=n)current*=10 else{
                while(current%10==9||current+1>n)current/=10;
                current++
            }
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<int> lexicalOrder(int n){
        vector<int> answer;
        answer.reserve(n);
        int current=1;
        for(int count=0;count<n;++count){
            answer.push_back(current);
            if((long long)current*10<=n)current*=10;
            else{
                while(current%10==9||current+1>n)current/=10;
                ++current;
            }
        }
        return answer;
    }
};
